/// A Duotone glyph's two layers.
class DuoIcon {
  const DuoIcon(this.primary, this.secondary);

  final IconData primary;
  final IconData secondary;
}

/// Draws a [DuoIcon]: the fill at 20% under the outline, one colour.
class DuoGlyph extends StatelessWidget {
  const DuoGlyph(this.icon, {super.key, required this.size, this.color});

  final DuoIcon icon;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) => ExcludeSemantics(
    child: Stack(
      alignment: Alignment.center,
      children: [
        Opacity(
          opacity: 0.2,
          child: Icon(icon.secondary, size: size, color: color),
        ),
        Icon(icon.primary, size: size, color: color),
      ],
    ),
  );
}

/// The platform's icon.
IconData platformIcon(String platform) => switch (platform) {
  'windows' => AppIcons.windows,
  'macos' => AppIcons.mac,
  'linux' => AppIcons.linux,
  'ios' || 'android' => AppIcons.phone,
  _ => AppIcons.windows,
};
